  if(!t.has(prefix+"Request")){t.put(prefix+"Request",UUID.randomUUID().toString());t.put(prefix+"Nonce",PhoneGateCore.b64(ProtocolCore.random(32)));}gate.put(t);
  KeyStore keys=KeyStore.getInstance("AndroidKeyStore");keys.load(null);String alias=local?t.getString("localPeerKey"):"ctpa-device-v1";Map<String,Object> body=new LinkedHashMap<>();body.put("requestId",operation.equals("start")?t.getString(prefix+"Request"):UUID.randomUUID().toString());body.put("installationId",installation);body.put("appVersion",PhoneGateCore.VERSION);body.put("releaseId",PhoneGateCore.RELEASE);body.put("timestamp",System.currentTimeMillis()/1000);body.put("nonce",operation.equals("start")?t.getString(prefix+"Nonce"):PhoneGateCore.b64(ProtocolCore.random(32)));body.put("publicKey",PhoneGateCore.b64(keys.getCertificate(alias).getPublicKey().getEncoded()));body.put("jobId",job);body.put("action",r?"receive":"send");body.put("scopeHash",plan.scope());if(operation.equals("outcome")){String checkpoint=options.getString("checkpointHash",local?null:t.optString("checkpoint"));PhoneGateCore.hashValue(checkpoint);body.put("checkpointHash",checkpoint);body.put("status",options.getString("terminal",local?"completed":t.optString("terminal")));}
  String path="/api/toolbox/client/v1/phone-assistant/jobs/"+operation,payload=PhoneGateCore.b64(PhoneGate.JSON.write(body).getBytes(java.nio.charset.StandardCharsets.UTF_8));Signature sign=Signature.getInstance("SHA256withECDSA");sign.initSign((PrivateKey)keys.getKey(alias,null));sign.update(PhoneGateCore.canonical(path,payload,body).getBytes(java.nio.charset.StandardCharsets.UTF_8));Map<String,Object> wire=new LinkedHashMap<>();wire.put("payload",payload);wire.put("signature",PhoneGateCore.b64(PhoneGateCore.derToRaw(sign.sign())));out.putString("path",path);out.putString("proof",PhoneGate.JSON.write(wire));out.putString("scopeHash",plan.scope());out.putString("evidenceScope","Actual Android Keystore public proof envelope; no network request or secret exported");
